/**
 * FolderItem Component - Displays a single folder
 * 
 * Responsibilities:
 * - Show folder name
 * - Handle folder click (navigate into)
 * - Show folder icon
 * 
 * Import rules:
 * - Can import: hooks (if needed)
 * - Can import: other components
 * - Should NOT import: services, pages
 */

import React, { useState } from 'react';

const FolderItem = ({ folder, onNavigate, onDelete }) => {
  const [isHovered, setIsHovered] = useState(false);

  const handleClick = (e) => {
    // Don't navigate if clicking on delete button
    if (e.target.closest('.folder-actions')) {
      return;
    }
    if (onNavigate) {
      onNavigate(folder.id, folder.name);
    }
  };

  return (
    <div 
      className="folder-item"
      onClick={handleClick}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      <div className="folder-icon">📁</div>
      <div className="folder-name" title={folder.name}>{folder.name}</div>
      {isHovered && (
        <div className="folder-actions" onClick={(e) => e.stopPropagation()}>
          {onDelete && (
            <button 
              className="btn-icon" 
              onClick={() => onDelete(folder.id)}
              title="Delete"
            >
              🗑️
            </button>
          )}
        </div>
      )}
    </div>
  );
};

export default FolderItem;
